let data = null;

if ($("Buscamos OK").isExecuted) {
   data = $('Buscamos OK').first().json;
} else {
   data = $('Inserta Cabecera').first().json;
}

let fechaFormateada = data.fecha_recepcion || '';

const fechaSheets = Number(fechaFormateada);

if (!isNaN(fechaSheets) && fechaSheets > 0) {
  const fecha = new Date((fechaSheets - 25569) * 86400 * 1000);
  fechaFormateada = fecha.toLocaleDateString('es-ES', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
  });
} 

return [{
  json: {
    ...data,
    fecha_recepcion: fechaFormateada
  }
}];

// La empresa del gasto siempre es del grupo (el prompt no deja a Gemini devolver nuestros CIF): si la hoja no trae uno de ellos, se deduce del nombre
const CIF_GRUPO = { MARSAF: 'B54874334', DIANIA: 'B54707906' };
const cifEmpresa = c => {
  const actual = String(c.empresa_cif ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '').replace(/^ES/, '');
  if (Object.values(CIF_GRUPO).includes(actual)) return actual;
  const nombre = String(c.empresa_nombre ?? '').toUpperCase();
  const clave = Object.keys(CIF_GRUPO).find(k => nombre.includes(k));
  return clave ? CIF_GRUPO[clave] : (c.empresa_cif ?? '');
};

let pdfBase64 = null;

if ($("Extract from File1").isExecuted) {
   pdfBase64 = $('Extract from File1').first().json.pdf_base64;
} else {
   pdfBase64 = $('Extract from File').first().json.pdf_base64;
}

const cabecera = $('Recuperamos fecha y hora').first().json;


const jsonT2000 = {
  cabecera: {
    CIFEmpresa: cifEmpresa(cabecera),
    NombreEmpresa: cabecera.empresa_nombre,
    FechaPedido: cabecera.fecha_pedido,
    NombreCliente: cabecera.cliente_nombre,
    CIFCliente: cabecera.cliente_cif,
    NumPedCliente: String(cabecera.numero_pedido ?? ''),
    NumGasto: cabecera.num_gasto,
    Observaciones: cabecera.observaciones,
    Persona: cabecera.email_origen,
    Precio: cabecera.precio,
    Comercial: String(cabecera.email_origen ?? '').split('@')[0].toUpperCase()
  },  
  documento: pdfBase64,  
  documento_nombre: cabecera.nombre_archivo
};

return [{ json: jsonT2000 }];

// Normaliza la respuesta de T2000 (o el error de la llamada) para decidir si se marca Procesado o Rechazado
return $input.all().map((item, i) => {
  const r = item.json;
  let ok = false, numero = '', pedido = '', info = '', motivo = '';

  if (r.error) {
    const e = r.error;
    motivo = 'Error llamando a T2000: ' + (typeof e === 'string' ? e : ([e.message, e.description].filter(Boolean).join(' — ') || JSON.stringify(e)));
  } else {
    try {
      const body = typeof r.data === 'string' ? JSON.parse(r.data) : r;
      ok = body.success === true;
      numero = body.numero ?? '';
      pedido = body.pedido ?? body.numero ?? '';
      info = body.info ?? '';
      motivo = info;
    } catch (e) {
      motivo = 'Respuesta no válida de T2000: ' + String(r.data);
    }
  }

  return { json: { ok, numero, pedido: String(pedido), info: String(info), motivo: String(motivo).slice(0, 500), data: r.data }, pairedItem: i };
});

